    function run(address newOwner, uint256 minAmount, uint256 rewardRate) public payable {
        c.changeOwner(newOwner);
        c.setMinTxnAmount(minAmount);
        c.setRewardRate(rewardRate);

        string memory symBefore = c.symbol();
        require(bytes(symBefore).length > 0, "precondition failed");

        // additional state-changing calls to ensure independence
        c.changeOwner(address(this));
        c.setMinTxnAmount(minAmount + 1);
        c.setRewardRate(rewardRate + 1);

        string memory symAfter = c.symbol();

        assert(bytes(symAfter).length > 0 && keccak256(bytes(symBefore)) == keccak256(bytes(symAfter)));
    }

    receive() external payable {}
}

