contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address recipient, uint256 amount) public {
        require(recipient != address(0), "recipient zero");
        require(amount > 0, "amount zero");
        require(amount <= c.totalSupply(), "amount too large");

        c.approve(address(this), amount);

        uint256 senderBalanceBefore = c.balanceOf(address(this));
        require(senderBalanceBefore >= amount, "sender lacks balance");
        uint256 allowanceBefore = c.allowance(address(this), address(this));

        bool reverted;
        try c.transferFrom(address(this), recipient, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 recipientBalanceAfter = c.balanceOf(recipient);
        uint256 allowanceAfter = c.allowance(address(this), address(this));

        assert(!reverted == (recipientBalanceAfter >= amount && allowanceAfter == allowanceBefore - amount));
    }

    receive() external payable {}
}

