contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address to, uint256 amount) public payable {
        require(to != address(0), "bad recipient");
        require(to != address(this), "bad recipient");
        require(amount > 0, "amount must be positive");
        require(c.balanceOf(address(this)) >= amount, "insufficient balance");

        uint256 balSenderBefore = c.balanceOf(address(this));
        uint256 balRecipientBefore = c.balanceOf(to);

        bool reverted;
        try c.transfer(to, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balSenderAfter = c.balanceOf(address(this));
        uint256 balRecipientAfter = c.balanceOf(to);

        if (!reverted) {
            assert(balSenderBefore > balSenderAfter);
            assert(balSenderBefore - balSenderAfter == amount);
            assert(balRecipientAfter > balRecipientBefore);
            assert(balRecipientAfter - balRecipientBefore >= amount);
        }
    }

    receive() external payable {}
}

