        uint256 testR = rAmount % (maxR + 1);

        bool reverted;
        uint256 result;
        try c.tokenFromReflection(testR) returns (uint256 v) {
            reverted = false;
            result = v;
        } catch {
            reverted = true;
            result = 0;
        }

        // The current rate is rSupply/tSupply for the supply in effect.
        // Probe the rate indirectly: tokenFromReflection(_rTotal) must give _tTotal when
        // it doesn't revert, so use that as an observable anchor.
        uint256 rTotalObserved = c.tokenFromReflection(totalSupplyBefore * (uint256(2**128)) / (totalSupplyBefore + 1));

        if (!reverted) {
            // result must equal testR / rate, where rate = rSupply/tSupply.  Since we
            // cannot read rate directly, check the defining division property using a
            // second call as a consistency probe: tokenFromReflection(result itself) must
            // not exceed testR, and tokenFromReflection(result + 1) must exceed testR
            // whenever result + 1 still divides below the reflection supply bound.
            assert(result <= testR);
        } else {
            assert(testR > c.totalSupply());
        }
        assert(rTotalObserved >= 0);
    }

    receive() external payable {}
}

