        }

        if (!reverted) {
            // v must be rAmount / rate, so v <= rAmount always.
            assert(result <= testR);

            // Consistency: tokenFromReflection(result) must not revert and must be <= testR,
            // since result is already the quotient floor.
            bool revertedResult;
            uint256 resultResult;
            try c.tokenFromReflection(result) returns (uint256 v2) {
                revertedResult = false;
                resultResult = v2;
            } catch {
                revertedResult = true;
                resultResult = 0;
            }
            assert(revertedResult ? testR >= 0 : resultResult <= testR);

            // Consistency: tokenFromReflection(result + 1) must exceed testR (or revert),
            // which pins down result as the floor of the division.
            bool revertedNext;
            uint256 nextResult;
            try c.tokenFromReflection(result + 1) returns (uint256 v3) {
                revertedNext = false;
                nextResult = v3;
            } catch {
                revertedNext = true;
                nextResult = 0;
            }
            assert(revertedNext || nextResult > testR);
        } else {
            // If it reverted, testR must be strictly greater than the reflection supply bound
            // implied by the total reflection supply; the only public observable is totalSupply().
            // We can at least assert testR is huge relative to supply, which is the documented guard.
            assert(testR > supply);
        }
    }

    receive() external payable {}
}

