contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address sender, address recipient, uint256 amount) public {
        // The transferFrom call must succeed for at least some inputs (checker ensures reachability).
        // We drive the public entry and capture the returned value.
        bool success;
        try c.transferFrom(sender, recipient, amount) returns (bool ret) {
            success = ret;
        } catch {
            success = false;
        }
        // The general rule: every successful transferFrom returns true.
        // (Failure/revert is allowed; the rule only constrains completing calls.)
        assert(!success || success == true);
    }

    receive() external payable {}
}

