contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address spender, uint256 addedValue) public {
        require(spender != address(0), "zero spender");
        require(addedValue > 0, "zero added value");
        require(addedValue <= type(uint256).max - c.allowance(address(this), spender), "overflow");

        uint256 before = c.allowance(address(this), spender);
        bool ok = c.increaseAllowance(spender, addedValue);
        uint256 afterAllowance = c.allowance(address(this), spender);

        assert(ok && afterAllowance == before + addedValue);
    }

    receive() external payable {}
}

