contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address recipient, uint256 amount) public {
        require(recipient != address(0), "recipient must not be zero");
        require(amount > 0, "amount must be positive");

        uint256 senderBalBefore = c.balanceOf(address(this));
        require(senderBalBefore >= amount, "test must have enough balance");
        uint256 recipientBalBefore = c.balanceOf(recipient);

        bool reverted;
        try c.transfer(recipient, amount) { reverted = false; } catch { reverted = true; }

        if (!reverted) {
            uint256 senderBalAfter = c.balanceOf(address(this));
            uint256 recipientBalAfter = c.balanceOf(recipient);
            assert(senderBalAfter == senderBalBefore - amount && recipientBalAfter == recipientBalBefore + amount);
        } else {
            assert(c.balanceOf(address(this)) == senderBalBefore && c.balanceOf(recipient) == recipientBalBefore);
        }
    }
}

