    }

    function run(uint256 newRate) public {
        uint256 before = c.rewardRate();
        address owner = c.owner();

        bool reverted;
        try c.setRewardRate(newRate) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(
            (msg.sender == owner && !reverted && c.rewardRate() == newRate)
            || (msg.sender != owner && reverted && c.rewardRate() == before)
        );
    }
}
